Given an array arr[] of size n, find the element that appears more than ⌊n/2⌋ times. If no such element exists, return -1.Examples:Input: arr[] = [1, 1, 2, 1, 3, 5, 1]Output: 1Explanation: Element 1 appears 4 times. Since ⌊7/2⌋ = 3, and 4 > 3, it is the majority element.Input: arr[] = [7]Output: 7Explanation: Element 7 appears once. Since ⌊1/2⌋ = 0, and 1 > 0, it is the majority element.Input: arr[] = [2, 13]Output: -1Explanation: No element appears more than ⌊2/2⌋ = 1 time, so there is no majority element.Try It YourselfTable of Content[Naive Approach] Using Two Nested Loops -  O(n^2) Time and O(1) Space[Expected Approach] Using Moore's Voting Algorithm - O(n) Time and O(1) Space[Naive Approach] Using Two Nested Loops -  O(n^2) Time and O(1) SpaceThe idea is to use nested loops to count frequencies. The outer loop selects each element as a candidate, and the inner loop counts how many times it appears. If any element appears more than n / 2 times, it is the majority element.
            C++

    #include <iostream>
#include <vector>
using namespace std;

int majorityElement(vector<int>& arr) {
    int n = arr.size();  

    // Loop to consider each element as a 
    // candidate for majority
    for (int i = 0; i < n; i++) {
        int count = 0; 

        // Inner loop to count the frequency of arr[i]
        for (int j = 0; j < n; j++) {
            if (arr[i] == arr[j]) {
                count++;
            }
        }

        // Check if count of arr[i] is more 
        // than half the size of the array
        if (count > n / 2) {
            return arr[i]; 
        }
    }

    // If no majority element found, return -1
    return -1;
}

int main() {
    vector<int> arr = {1, 1, 2, 1, 3, 5, 1};

    cout << majorityElement(arr) << endl;

    return 0;
}


